sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var pref = api.data.get_user_preference.output.data.GlideDomain_Query.user.preferences[0].value;
    var pref_obj = pref && pref.length !=0 ? JSON.parse(pref) : {filter:[],columnData:[]};
    api.setState("filter", JSON.stringify(pref_obj.filter));
    api.setState("parFilters",pref_obj.filter);
    api.setState("colmnData", pref_obj.columnData);
}
